    if F(T('fourth_wheel'),T('escape_pinion'))*60!=F(I['beats_per_hour'],30): E.append('resc')
    if F(T('cannon_pinion'),T('minute_wheel'))*F(T('minute_pinion'),T('hour_wheel'))!=F(1,12): E.append('r12')
    pr=6.5*T('barrel_wheel')/T('centre_pinion')
    if pr<I['power_reserve_target_h']: E.append('pr')
