    lv=lambda n:({G[n]['level'],G[n]['level']+1} if n=='barrel_wheel' else {G[n]['level']}) if n in GT else {('d',G[n]['dial_level'])}
    for a,b in MESH:
        if abs(G[a]['module']-G[b]['module'])>1e-12: E.append('mm')
        key='level' if a in GT else 'dial_level'
        if G[a][key]!=G[b][key]: E.append('ml '+a)
        if abs(d(pos(a),pos(b))-G[a]['module']*(T(a)+T(b))/2)>0.004: E.append('md '+a)
