        if (n1,n2) in MESH or (n2,n1) in MESH: continue
        if l1&l2 and d(p1,p2)<r1+r2+0.10+1e-6: E.append('coll %s %s'%(n1,n2))
    for n,p,r,l in items[:-1]:
        if d(p,C)+r>R-0.30-1e-6: E.append('plate '+n)
